window.__ModuleLoader__.load({
  id: '@local/notification-chime',
  factory() {
    const CHIME_AUDIO_BASE64 = ''
    const STORAGE_KEY = '@local/notification-chime:seen'
    let audioContext
    let cueBuffer
    let cueLoading

    /** Remember keys for a day so re-showing an old question card does not ring. */
    function loadSeen() {
      try {
        const raw = sessionStorage.getItem(STORAGE_KEY)
        const parsed = raw ? JSON.parse(raw) : null
        if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) {
          const cutoff = Date.now() - 24 * 60 * 60 * 1000
          return new Map(Object.entries(parsed).filter(([, at]) => typeof at === 'number' && at > cutoff))
        }
      } catch {
        // Storage may be unavailable in a restricted browser context.
      }
      return new Map()
    }

    function saveSeen(seen) {
      try {
        sessionStorage.setItem(STORAGE_KEY, JSON.stringify(Object.fromEntries(seen)))
      } catch {
        // The in-memory map still works for this page generation.
      }
    }

    /** Return the cue's lazily created AudioContext, when the browser has one. */
    function ensureAudio() {
      if (typeof window === 'undefined') return undefined
      const AudioContextClass = window.AudioContext || window.webkitAudioContext
      if (!AudioContextClass) return undefined
      if (!audioContext) {
        try {
          audioContext = new AudioContextClass()
        } catch {
          return undefined
        }
      }
      return audioContext
    }

    /** Decode the bundled clip once per page generation; undefined when it cannot decode. */
    function decodeCue(audio) {
      if (cueBuffer) return Promise.resolve(cueBuffer)
      if (!cueLoading) {
        const binary = atob(CHIME_AUDIO_BASE64)
        const bytes = new Uint8Array(binary.length)
        for (let index = 0; index < binary.length; index += 1) bytes[index] = binary.charCodeAt(index)
        cueLoading = audio.decodeAudioData(bytes.buffer)
          .then(buffer => {
            cueBuffer = buffer
            return buffer
          })
          .catch(() => undefined)
      }
      return cueLoading
    }

    /** Fallback cue: a short two-note bell when the clip cannot be decoded. */
    function playNotes(audio) {
      const now = audio.currentTime
      // A soft bell-like "ding-dong": A5 followed by D6.
      const notes = [
        { frequency: 880, at: 0, length: 0.2, peak: 0.3 },
        { frequency: 1174.66, at: 0.15, length: 0.34, peak: 0.26 },
      ]
      for (const note of notes) {
        const start = now + note.at
        const oscillator = audio.createOscillator()
        const gain = audio.createGain()
        oscillator.type = 'sine'
        oscillator.frequency.setValueAtTime(note.frequency, start)
        // Quick attack, long exponential tail: bell-like instead of a click.
        gain.gain.setValueAtTime(0.0001, start)
        gain.gain.exponentialRampToValueAtTime(note.peak, start + 0.02)
        gain.gain.exponentialRampToValueAtTime(0.0001, start + note.length)
        oscillator.connect(gain)
        gain.connect(audio.destination)
        oscillator.start(start)
        oscillator.stop(start + note.length + 0.02)
        oscillator.onended = () => {
          oscillator.disconnect()
          gain.disconnect()
        }
      }
    }

    /** Play the bundled cue through the unlocked AudioContext. */
    function playCue() {
      const audio = ensureAudio()
      if (!audio) return
      const start = () => {
        void decodeCue(audio).then(buffer => {
          if (!buffer) {
            playNotes(audio)
            return
          }
          const source = audio.createBufferSource()
          const gain = audio.createGain()
          source.buffer = buffer
          source.connect(gain)
          gain.connect(audio.destination)
          source.start()
          source.onended = () => {
            source.disconnect()
            gain.disconnect()
          }
        })
      }
      if (audio.state === 'running') {
        start()
      } else if (audio.state === 'suspended') {
        // Autoplay policy may defer the resume; play as soon as it settles.
        void audio.resume()
          .then(() => { if (audio.state === 'running') start() })
          .catch(() => {})
      }
    }

    /**
     * Stable identity for one pending interaction. Approval keys restart from
     * `approval:1` on every page load, so the correlated tool call id is used
     * when the domain supplies one.
     */
    function keysOf(snapshot) {
      const keys = new Set()
      for (const [sessionId, status] of snapshot) {
        const interaction = status && status.pendingInteraction
        if (!interaction || !interaction.key) continue
        const stable = typeof interaction.callId === 'string' && interaction.callId !== ''
          ? `call:${interaction.callId}`
          : `key:${interaction.key}`
        keys.add(`${sessionId}:${interaction.kind || ''}:${stable}`)
      }
      return keys
    }

    return {
      inject: ['uiSession'],
      apply(ctx) {
        ctx.effect(() => {
          const source = ctx.uiSession.sessionStatus
          const seen = loadSeen()

          // Seed from the current view so a page load never rings for old cards.
          for (const key of keysOf(source.getSnapshot())) {
            if (!seen.has(key)) seen.set(key, Date.now())
          }
          saveSeen(seen)

          const unsubscribe = source.subscribe(() => {
            const current = keysOf(source.getSnapshot())
            let isNew = false
            for (const key of current) {
              if (!seen.has(key)) {
                seen.set(key, Date.now())
                isNew = true
              }
            }
            if (isNew) {
              saveSeen(seen)
              playCue()
            }
          })

          // Browsers can keep audio suspended until the first user gesture.
          // Keep trying on each gesture until the context is actually running.
          const unlock = () => {
            const audio = ensureAudio()
            if (!audio) return
            const ready = () => {
              if (audio.state === 'running') {
                document.removeEventListener('pointerdown', unlock, true)
                document.removeEventListener('keydown', unlock, true)
              }
            }
            if (audio.state === 'suspended') void audio.resume().then(ready).catch(() => {})
            else ready()
          }
          document.addEventListener('pointerdown', unlock, true)
          document.addEventListener('keydown', unlock, true)

          return () => {
            unsubscribe()
            document.removeEventListener('pointerdown', unlock, true)
            document.removeEventListener('keydown', unlock, true)
            if (audioContext) {
              void audioContext.close().catch(() => {})
              audioContext = undefined
            }
          }
        }, 'notification-chime: pending interaction sound')
      },
    }
  },
})
